head.script:
// 샘플에 직접 유효성 설정
scwin.tData = {
    "description" : "[multiselect > M > getIdxValue]<br/>인덱스를 사용하여 특정 아이템의 Value 값을 반환합니다.",
    "validation" : [
        "index(필수) 파라미터로 Value 값을 조회할 아이템의 인덱스를 설정합니다.",
        "인덱스는 0 부터 시작합니다.",
        "지정한 인덱스에 해당하는 아이템의 Value 값을 반환합니다.",
        "파라미터의 인덱스값이 유효 범위를 벗어나면 false 를 반환합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성 (BindItemSet: gdl_multiselect 바인딩)
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // gdl_multiselect 재생성 (idempotent: 기존 dataList 제거 후 재생성)
    $c.gcm.createDataListMultiSelect();

    // comp 생성 함수 호출 (gdl_multiselect 바인딩 → 인덱스 0,1,2 / value=1,2,3)
    $c.gcm.createBasicMultiSelect();
}



// getIdxValue 호출 (par_index 입력값으로 특정 아이템의 Value 반환)
// index : 조회할 아이템의 인덱스 (0 부터 시작)
scwin.btn_getIdxValue_onclick = function (e) {
    let strIndex = par_index.getValue();
    let index = parseInt(strIndex, 10);
    let rtn = target1.getIdxValue(index);

    wf_body_bottom.getObj("scwin").setReturnValue("target1.getIdxValue(" + index + ") : [" + rtn + "]");
    wf_body_bottom.getObj("scwin").setReturnValue("typeof rtn : " + typeof rtn);
};
